sql.if:
and (p.owner_user_id = #{params.projectAccessUserId}
     or exists (select 1 from review_project_member pm
                where pm.project_id = p.project_id
                  and pm.user_id = #{params.projectAccessUserId}
                  and pm.status = '0'))

mapper.sql:

    AND r.create_time >= #{params.beginDate}


    AND r.create_time < #{params.endDateExclusive}


    AND p.project_id = #{projectId}


    AND r.snapshot_model_id = #{modelId}

${params.dataScope}

mapper.select:
SELECT MIN(r.create_time)

WHERE r.total_tokens IS NOT NULL
${params.dataScope}
